// SPDX-License-Identifier: MIT
pragma solidity 0.8.15;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/DinoXInuContract.sol";

contract TestTotalSupplyDiversion is Test {
    DinoXInuContract token;
    address constant deadWallet = 0x000000000000000000000000000000000000dEaD;
    address ownerAddress;

    function setUp() public {
        token = new DinoXInuContract();
        ownerAddress = token.owner();
    }

    function testManualBurnAccounting() public {
        uint256 decimals = token.decimals();
        uint256 burnAmount = 1000 * (10 ** decimals);

        uint256 initialTotalSupply = token.totalSupply();
        uint256 initialOwnerBalance = token.balanceOf(ownerAddress);
        uint256 initialDeadBalance = token.balanceOf(deadWallet);

        token.manualBurn(burnAmount);

        uint256 newTotalSupply = token.totalSupply();
        uint256 newOwnerBalance = token.balanceOf(ownerAddress);
        uint256 newDeadBalance = token.balanceOf(deadWallet);
        uint256 totalBalances = newOwnerBalance + newDeadBalance;

        // Validate expected changes
        assertEq(
            newTotalSupply,
            initialTotalSupply - burnAmount,
            "Total supply not decreased by burn amount"
        );

        assertEq(
            newOwnerBalance,
            initialOwnerBalance - (2 * burnAmount),
            "Owner balance not decreased by 2*burnAmount (double loss)"
        );

        assertEq(
            newDeadBalance,
            initialDeadBalance + burnAmount,
            "Dead wallet not increased by burnAmount"
        );

        // Verify reflection token invariant - total balances should equal total supply
        assertEq(
            totalBalances,
            newTotalSupply,
            "Sum of balances should equal total supply after reflection calculations"
        );
    }
}
